import "jsr:@supabase/functions-js/edge-runtime.d.ts";
import { createClient } from "jsr:@supabase/supabase-js@2";
import { localeFromCountryCode } from "../_shared/locale-from-country.ts";
import { buildWelcomeEmail } from "../_shared/shopify-welcome-templates.ts";
import { sendZohoEmail } from "../_shared/zoho-mail.ts";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
  "Access-Control-Allow-Headers":
    "Content-Type, Authorization, X-Client-Info, Apikey, X-Shopify-Welcome-Email-Secret",
};

type WelcomeEmailBody = {
  shop_domain?: string;
  shop_name?: string;
  shop_email?: string;
  country_code?: string;
  locale?: "pt" | "es" | "en";
  force?: boolean;
};

function jsonResponse(body: Record<string, unknown>, status = 200): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...corsHeaders, "Content-Type": "application/json" },
  });
}

function unauthorized(message: string): Response {
  return jsonResponse({ error: message }, 401);
}

Deno.serve(async (req: Request) => {
  if (req.method === "OPTIONS") {
    return new Response(null, { status: 200, headers: corsHeaders });
  }

  if (req.method !== "POST") {
    return jsonResponse({ error: "Method not allowed" }, 405);
  }

  const welcomeSecret = Deno.env.get("SHOPIFY_WELCOME_EMAIL_SECRET")?.trim();
  if (welcomeSecret) {
    const headerSecret = req.headers.get("X-Shopify-Welcome-Email-Secret")?.trim();
    if (headerSecret !== welcomeSecret) {
      return unauthorized("Invalid X-Shopify-Welcome-Email-Secret");
    }
  }

  let body: WelcomeEmailBody;
  try {
    body = (await req.json()) as WelcomeEmailBody;
  } catch {
    return jsonResponse({ error: "Invalid JSON body" }, 400);
  }

  const shopDomain = body.shop_domain?.trim().toLowerCase();
  const shopName = body.shop_name?.trim();
  const shopEmail = body.shop_email?.trim().toLowerCase();

  if (!shopDomain || !shopName || !shopEmail) {
    return jsonResponse({
      error: "shop_domain, shop_name, and shop_email are required",
    }, 400);
  }

  const supabase = createClient(
    Deno.env.get("SUPABASE_URL") ?? "",
    Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? "",
  );

  const { data: existingSend, error: lookupError } = await supabase
    .from("shopify_welcome_emails")
    .select("sent_at")
    .eq("shop_domain", shopDomain)
    .maybeSingle();

  if (lookupError) {
    console.error("[shopify-welcome-email] lookup failed:", lookupError);
    return jsonResponse({ error: "Failed to lookup welcome email record" }, 500);
  }

  if (existingSend?.sent_at && !body.force) {
    return jsonResponse({
      ok: true,
      skipped: true,
      reason: "already_sent",
      sent_at: existingSend.sent_at,
    });
  }

  const locale = body.locale ?? localeFromCountryCode(body.country_code);
  const emailContent = buildWelcomeEmail(locale, shopName);

  try {
    const messageId = await sendZohoEmail({
      toAddress: shopEmail,
      subject: emailContent.subject,
      htmlContent: emailContent.html,
      textContent: emailContent.text,
    });

    const sentAt = new Date().toISOString();
    const { error: insertError } = await supabase
      .from("shopify_welcome_emails")
      .upsert(
        {
          shop_domain: shopDomain,
          shop_contact_email: shopEmail,
          shop_country_code: body.country_code?.trim().toUpperCase() ?? null,
          locale,
          zoho_message_id: messageId,
          sent_at: sentAt,
        },
        { onConflict: "shop_domain" },
      );

    if (insertError) {
      console.error("[shopify-welcome-email] tracking insert failed:", insertError);
    }

    await supabase.from("shopify_uninstall_emails").delete().eq("shop_domain", shopDomain);

    await supabase
      .from("shopify_shops")
      .update({
        shop_contact_email: shopEmail,
        shop_country_code: body.country_code?.trim().toUpperCase() ?? null,
        welcome_email_sent_at: sentAt,
        updated_at: sentAt,
      })
      .eq("shop_domain", shopDomain);

    return jsonResponse({
      ok: true,
      skipped: false,
      locale,
      message_id: messageId,
      sent_at: sentAt,
    });
  } catch (error) {
    console.error("[shopify-welcome-email] send failed:", error);
    return jsonResponse({
      error: error instanceof Error ? error.message : "Failed to send welcome email",
    }, 500);
  }
});

export type WelcomeLocale = "pt" | "es" | "en";

const PORTUGUESE_COUNTRIES = new Set([
  "BR", "PT", "AO", "MZ", "CV", "GW", "ST", "TL",
]);

const SPANISH_COUNTRIES = new Set([
  "ES", "MX", "AR", "CO", "CL", "PE", "VE", "EC", "GT", "CU", "BO", "DO",
  "HN", "PY", "SV", "NI", "CR", "PA", "UY", "PR", "GQ",
]);

export function localeFromCountryCode(
  countryCode: string | null | undefined,
): WelcomeLocale {
  const code = (countryCode ?? "").trim().toUpperCase();
  if (!code) return "en";
  if (PORTUGUESE_COUNTRIES.has(code)) return "pt";
  if (SPANISH_COUNTRIES.has(code)) return "es";
  return "en";
}

import type { WelcomeLocale } from "./locale-from-country.ts";

export type WelcomeEmailContent = {
  subject: string;
  html: string;
  text: string;
};

const SUPPORT_EMAIL = "contato@omafit.co";
const DOCS_URL = "https://omafit.co";

function escapeHtml(value: string): string {
  return value
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;");
}

export function buildWelcomeEmail(
  locale: WelcomeLocale,
  shopName: string,
): WelcomeEmailContent {
  const safeShopName = escapeHtml(shopName);

  const copy = {
    pt: {
      subject: "Bem-vindo ao Omafit — podemos ajudar na implementação?",
      greeting: `Olá, equipe da ${shopName}!`,
      intro:
        "Obrigado por instalar o Omafit na sua loja Shopify. Estamos felizes em ter você conosco.",
      help:
        "Precisa de ajuda para configurar o provador virtual, widget ou integração? Responda este e-mail — nossa equipe orienta você passo a passo.",
      cta: "Visitar o Omafit",
      signOff: "Abraços,\nEquipe Omafit",
    },
    es: {
      subject: "Bienvenido a Omafit — ¿necesitas ayuda con la implementación?",
      greeting: `¡Hola, equipo de ${shopName}!`,
      intro:
        "Gracias por instalar Omafit en tu tienda Shopify. Nos alegra tenerte con nosotros.",
      help:
        "¿Necesitas ayuda para configurar el probador virtual, el widget o la integración? Responde a este correo y te guiaremos paso a paso.",
      cta: "Visitar Omafit",
      signOff: "Saludos,\nEquipo Omafit",
    },
    en: {
      subject: "Welcome to Omafit — need help getting set up?",
      greeting: `Hi ${shopName} team,`,
      intro:
        "Thanks for installing Omafit on your Shopify store. We're excited to have you on board.",
      help:
        "Need help setting up virtual try-on, the widget, or your integration? Reply to this email and our team will walk you through it.",
      cta: "Visit Omafit",
      signOff: "Best,\nThe Omafit team",
    },
  }[locale];

  const text = [
    copy.greeting,
    "",
    copy.intro,
    "",
    copy.help,
    "",
    `${copy.cta}: ${DOCS_URL}`,
    "",
    copy.signOff,
    SUPPORT_EMAIL,
  ].join("\n");

  const html = `<!DOCTYPE html>
<html lang="${locale}">
  <body style="font-family: Inter, Arial, sans-serif; line-height: 1.6; color: #1f2937; max-width: 560px; margin: 0 auto; padding: 24px;">
    <p style="font-size: 18px; font-weight: 600;">${escapeHtml(copy.greeting)}</p>
    <p>${escapeHtml(copy.intro)}</p>
    <p>${escapeHtml(copy.help)}</p>
    <p style="margin: 28px 0;">
      <a href="${DOCS_URL}" style="background: #8b5cf6; color: #ffffff; text-decoration: none; padding: 12px 20px; border-radius: 8px; display: inline-block;">
        ${escapeHtml(copy.cta)}
      </a>
    </p>
    <p style="white-space: pre-line; color: #4b5563;">${escapeHtml(copy.signOff)}</p>
    <p style="color: #6b7280; font-size: 14px;">${SUPPORT_EMAIL}</p>
  </body>
</html>`;

  return {
    subject: copy.subject,
    html,
    text,
  };
}

type ZohoTokenResponse = {
  access_token?: string;
  error?: string;
};

type ZohoSendResponse = {
  status?: { code?: number; description?: string };
  data?: { messageId?: string };
};

let cachedAccessToken: { token: string; expiresAt: number } | null = null;

function accountsBaseUrl(): string {
  return (Deno.env.get("ZOHO_ACCOUNTS_URL") ?? "https://accounts.zoho.com").replace(/\/$/, "");
}

function mailApiBaseUrl(): string {
  return (Deno.env.get("ZOHO_MAIL_API_URL") ?? "https://mail.zoho.com").replace(/\/$/, "");
}

async function refreshAccessToken(): Promise<string> {
  const clientId = Deno.env.get("ZOHO_CLIENT_ID")?.trim();
  const clientSecret = Deno.env.get("ZOHO_CLIENT_SECRET")?.trim();
  const refreshToken = Deno.env.get("ZOHO_REFRESH_TOKEN")?.trim();

  if (!clientId || !clientSecret || !refreshToken) {
    throw new Error("Missing ZOHO_CLIENT_ID, ZOHO_CLIENT_SECRET, or ZOHO_REFRESH_TOKEN");
  }

  const params = new URLSearchParams({
    refresh_token: refreshToken,
    client_id: clientId,
    client_secret: clientSecret,
    grant_type: "refresh_token",
  });

  const response = await fetch(`${accountsBaseUrl()}/oauth/v2/token`, {
    method: "POST",
    headers: { "Content-Type": "application/x-www-form-urlencoded" },
    body: params.toString(),
  });

  const payload = (await response.json()) as ZohoTokenResponse;
  if (!response.ok || !payload.access_token) {
    throw new Error(payload.error ?? `Zoho token refresh failed (${response.status})`);
  }

  cachedAccessToken = {
    token: payload.access_token,
    expiresAt: Date.now() + 50 * 60 * 1000,
  };

  return payload.access_token;
}

async function getAccessToken(): Promise<string> {
  if (cachedAccessToken && cachedAccessToken.expiresAt > Date.now()) {
    return cachedAccessToken.token;
  }
  return refreshAccessToken();
}

export type SendZohoEmailInput = {
  toAddress: string;
  subject: string;
  htmlContent: string;
  textContent: string;
  fromAddress?: string;
};

export async function sendZohoEmail(input: SendZohoEmailInput): Promise<string> {
  const accountId = Deno.env.get("ZOHO_ACCOUNT_ID")?.trim();
  const fromAddress = (input.fromAddress ?? Deno.env.get("ZOHO_FROM_ADDRESS") ?? "contato@omafit.co").trim();

  if (!accountId) {
    throw new Error("Missing ZOHO_ACCOUNT_ID");
  }

  const accessToken = await getAccessToken();
  const response = await fetch(`${mailApiBaseUrl()}/api/accounts/${accountId}/messages`, {
    method: "POST",
    headers: {
      Accept: "application/json",
      "Content-Type": "application/json",
      Authorization: `Zoho-oauthtoken ${accessToken}`,
    },
    body: JSON.stringify({
      fromAddress,
      toAddress: input.toAddress,
      subject: input.subject,
      content: input.htmlContent,
      mailFormat: "html",
      askReceipt: "no",
    }),
  });

  const payload = (await response.json()) as ZohoSendResponse;
  if (!response.ok || payload.status?.code !== 200) {
    throw new Error(
      payload.status?.description ?? `Zoho Mail send failed (${response.status})`,
    );
  }

  return payload.data?.messageId ?? "sent";
}
